steps.script:
$ErrorActionPreference='Stop'
$o=@{state='pending'}
$t=Join-Path $env:TEMP ('TTEditorialFix-'+[guid]::NewGuid().ToString('N')+'.ps1')
try{
 $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/6fc303c0da16ccbaabe8edc23f30d7fe7e30bd27/windows/Reparar-TT-Editorial-20261111.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $t -TimeoutSec 35
 $src=[IO.File]::ReadAllText($t,[Text.Encoding]::UTF8)
 if(-not $src.Contains('home route can restore a previous conversation or draft') -or -not $src.Contains('TT_EDITORIAL_SAFE_WRAPPER_V1')){throw 'PINNED_FIX_MARKER_MISSING'}
 & $t -NoDispatch *> $null
 if(-not $?){throw 'INSTALLER_FAILED'}
 $guard=Get-Content 'C:\TTiTTulares\TT-Editorial-Guard.js' -Raw
 if(-not $guard.Contains('home route can restore a previous conversation or draft')){throw 'GUARD_NOT_UPDATED'}
 $o.state='installed_verified'
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
finally{Remove-Item $t -Force -ErrorAction SilentlyContinue}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
